import type { Nullable } from "../../../types/index";
/**
 * The name a link reaches an anchor by: its `id`, or in older content its
 * `name`
 */
export declare function getAnchorName(anchor: HTMLAnchorElement): string;
/**
 * An anchor: an `<a>` with a name, no `href` and nothing in it
 */
export declare function isAnchor(node: Nullable<Node>): node is HTMLAnchorElement;
/**
 * The anchors in `root`, in the order they come
 */
export declare function getAnchors(root: ParentNode): HTMLAnchorElement[];
